import type { Revision } from './question-revisions';

// Each wrong choice is paired with its own causal error, not a generic warning.
const rows = `
p01-l05:1|A battery drives a steady current through a resistor. What role does the battery perform?|It maintains a potential difference that transfers energy to the circuit.|It supplies electrons that the resistor consumes.~Charge is not consumed by a resistor; energy is transferred.|It fixes the same current for every connected resistance.~A voltage source does not impose the same current on every load.|It removes the resistor’s opposition to charge flow.~The resistance remains part of the circuit and affects current.|The battery supplies energy per unit charge. With a complete path, its potential difference drives current determined by the connected circuit.|A source transfers energy; a load does not use up charge.|A lamp uses energy. Must the current leaving it be smaller than the current entering it in steady operation?|No. Charge is conserved; the same steady current enters and leaves the lamp.
p01-l05:2|A simple battery–lamp circuit is opened at one point. What happens after the switching transient?|Steady current through the lamp stops, but voltage can remain across the opening.|The battery loses its voltage because current stops.~An open circuit does not remove the source’s potential difference.|Charge continues steadily into the lamp and accumulates there.~A broken return path prevents sustained steady current in this simple circuit.|Both sides of the opening must become safe to touch.~Lack of load current does not prove absence of hazardous voltage.|A steady current needs a complete path through the source and load. Opening that path stops the steady flow; it does not establish isolation of every point.|No current is different from no voltage.|Why can an unlit lamp holder still require safe isolation before work?|The line connection may remain energised even when the normal load-current path is open.
p01-l05:3|A normal wall switch controls a lamp. What additional role does the circuit’s overcurrent device provide?|It disconnects excessive current according to its operating characteristic.|It sets the lamp brightness by continuously regulating current.~An ordinary overcurrent device is not a brightness regulator.|It replaces the switch whenever the lamp is turned off.~Normal control and automatic overcurrent operation are different functions.|It proves the lamp holder is dead whenever the lamp goes out.~Device or load state alone does not prove safe isolation.|A control switch permits normal operation. An overcurrent protective device responds to specified excess-current conditions; neither observation alone proves conductors safe for work.|Control, overcurrent protection and isolation have distinct purposes.|Does switching an appliance off prove that its circuit has adequate fault protection?|No. Normal control operation does not test the protective arrangement.
p01-l06:1|What does a voltage measurement between two points describe?|The difference in electrical potential energy per unit charge.|The amount of charge passing one point each second.~Charge per second is current.|The total charge stored between the points.~Stored charge is an amount, not energy per charge.|The total energy a load will use over its operating period.~Energy use also depends on current and operating time.|Voltage compares two points and expresses energy per unit charge. Current instead describes the rate of charge transfer through a point.|Voltage is measured between points; current is measured through a path.|Can a battery have terminal voltage while supplying no load current?|Yes. A potential difference can exist across an open circuit.
p01-l06:2|A 12 V source supplies a resistor. Its resistance rises from 6 Ω to 12 Ω. What happens to current?|It falls from 2 A to 1 A.|It rises from 2 A to 4 A.~At fixed voltage, increasing resistance reduces current.|It stays at 2 A because source voltage is unchanged.~Current depends on resistance as well as voltage.|It falls to zero because the resistance has increased.~A finite larger resistance reduces current; it does not create an open circuit.|For a resistive load, current equals voltage divided by resistance. Doubling resistance at the same applied voltage halves the current.|State what stays constant before predicting a change.|At the same voltage, what happens if the resistance is halved instead?|Current doubles, provided the resistive model and source voltage remain valid.
p01-l06:3|A resistor’s voltage and resistance are both doubled. What happens to its current?|It stays the same.|It doubles because the voltage doubles.~The simultaneous resistance increase offsets the voltage increase.|It halves because the resistance doubles.~The simultaneous voltage increase offsets the resistance increase.|It increases fourfold because both quantities double.~Current depends on the ratio of voltage to resistance, not their product.|Current is the ratio of voltage to resistance. Multiplying both by the same factor leaves that ratio unchanged.|Two changing quantities must be considered together.|What happens to current if voltage doubles while resistance stays fixed?|It doubles.
p01-l07:1|A resistive training circuit has known voltage and resistance. Which relationship gives current?|Divide voltage by resistance.|Multiply voltage by resistance.~The product does not have the units of current.|Divide resistance by voltage.~This reverses the required ratio and gives inverse amperes.|Divide voltage squared by resistance.~That expression gives resistive power, not current.|Rearranging voltage equals current times resistance gives current as voltage divided by resistance. The unit check is volts divided by ohms, giving amperes.|Choose the relationship for the requested quantity, not just the available numbers.|Which relationship finds resistance when voltage and current are known?|Resistance is voltage divided by current.
p01-l07:2|A resistor carries 3 A with 12 V across it. What is its resistance?|4 Ω.|36 Ω.~Multiplying voltage by current gives power, not resistance.|0.25 Ω.~Current divided by voltage is conductance, not resistance.|9 Ω.~Subtracting different physical quantities does not give resistance.|Divide the voltage across the resistor by its current. Twelve volts divided by three amperes is four ohms.|Resistance uses voltage divided by current; power uses their product.|A 4 Ω resistor carries 2 A. What voltage is across it?|8 V, from voltage equals current times resistance.
p01-l07:3|A filament’s temperature rises and its resistance increases. Why can a constant-resistance prediction become inaccurate?|The calculation used a resistance that no longer describes the operating state.|Ohm’s law requires every material to keep the same resistance at every temperature.~A fixed-resistance assumption is not valid for every material and condition.|The filament starts consuming electric charge when it becomes hot.~Heating transfers energy; it does not consume charge.|The supply voltage must increase whenever resistance rises.~A regulated source can maintain voltage while current changes.|A calculation is only as good as its component model. If resistance changes with temperature, use the resistance appropriate to the operating condition.|An equation does not guarantee that a parameter stays constant.|Would measuring a hot filament’s current justify using its cold resistance to predict that same operating point?|No. The resistance must correspond to the relevant temperature and operating state.
p01-l08:1|Two unequal resistors are in one series path. How do their steady currents compare?|Both carry the same current.|The larger resistor carries less current than the smaller one.~There is no branch between them for current to divide.|The second resistor carries less because the first uses some current.~Resistors transfer energy but do not consume charge.|Both carry half the source current.~Current division occurs at branches, not along one series path.|In a steady single path, charge cannot continually accumulate at a connection. The same charge per second therefore passes each component.|Series components share current, not necessarily voltage.|If one series connection opens, which resistor loses its steady current?|Both do, because the single complete path is broken.
p01-l08:2|Two resistors of 4 Ω and 6 Ω are connected in series. What resistance does the source see?|10 Ω.|2.4 Ω.~That is the parallel equivalent, not the series total.|6 Ω.~Both resistors contribute opposition; the smaller one does not disappear.|2 Ω.~Series resistances add rather than subtract.|The same current produces a voltage drop across each resistance. Adding the drops gives total resistance equal to the sum: ten ohms.|Use the connection arrangement before choosing the combination rule.|What happens to total series resistance when a third resistor is added?|It increases by the value of that resistor.
p01-l08:3|A 20 V source supplies 4 Ω and 6 Ω resistors in series. Which voltage pair is correct?|8 V across 4 Ω and 12 V across 6 Ω.|10 V across each resistor.~Equal voltage division requires equal resistances in this series model.|20 V across each resistor.~That would describe equal-voltage parallel branches, not this series connection.|12 V across 4 Ω and 8 V across 6 Ω.~At the same current, the larger resistance has the larger voltage drop.|Total resistance is ten ohms, giving two amperes through both resistors. Their voltage drops are current times resistance and add to the twenty-volt supply.|In series, voltage divides in proportion to resistance.|If both series resistors had the same resistance, how would the supply voltage divide?|Equally between them.
p01-l09:1|A 6 Ω and a 12 Ω resistor are connected in parallel across 12 V. What voltage is across each branch?|12 V across each branch.|6 V across each branch.~Parallel branches do not divide source voltage between them.|4 V across 6 Ω and 8 V across 12 Ω.~That proportional voltage division belongs to a series connection.|12 V across the lower resistance and 0 V across the other.~Both branches connect to the same two source points.|Each parallel branch is connected between the same two nodes. Their potential difference is therefore the same, while their currents can differ.|Parallel branches share voltage, not necessarily current.|If one branch is opened while the ideal source stays at 12 V, what voltage remains across the other branch?|12 V.
p01-l09:2|Two parallel branches carry 2 A and 1 A. What current does the source supply?|3 A.|1.5 A.~The source supplies the sum, not the average, of branch currents.|2 A.~The smaller branch still contributes to the source current.|1 A.~Subtracting outgoing branch currents does not conserve current at the split.|The source current divides at the junction and recombines in the return. In steady operation, the incoming current equals the sum of outgoing branch currents.|Current splits at a junction; it does not disappear.|Three branches each carry 0.5 A. What is the source current?|1.5 A.
p01-l09:3|Another finite resistor is added in parallel across an ideal voltage source. What happens to equivalent resistance?|It decreases because the additional branch increases total current at the same voltage.|It increases because more resistor material is connected.~More series resistance raises total resistance; another parallel path has the opposite effect.|It stays fixed because source voltage is fixed.~Fixed voltage does not imply fixed equivalent resistance.|It becomes the sum of the individual resistances.~That is the series-combination rule.|The extra branch draws additional current without changing the ideal source voltage. Since equivalent resistance is voltage divided by total current, the equivalent resistance falls.|An added parallel load increases supply demand while lowering equivalent resistance.|If a parallel branch is removed, what happens to equivalent resistance of the remaining network?|It increases, provided at least one conducting branch remains.
p01-l10:1|Two parallel branches have conductances of 0.10 S and 0.20 S. What is their combined conductance?|0.30 S.|0.0667 S.~Applying the reciprocal resistance rule directly to conductance reverses the combination.|0.10 S.~Subtracting discards part of the available conduction.|0.20 S.~The smaller branch still adds conductance.|Conductance describes current per volt. Parallel branches share voltage, so their conductances add just as their currents add.|Parallel conductances add directly; parallel resistances do not.|What resistance corresponds to 0.25 S of conductance?|4 Ω, because resistance is the reciprocal of conductance.
p01-l10:2|Two unequal resistors are in parallel. Which method gives their equivalent resistance?|Add their reciprocal resistances, then take the reciprocal of the sum.|Add their resistance values directly.~Direct addition applies to series resistors.|Average their resistance values.~An average does not account for current through both parallel paths.|Use the smaller resistance and ignore the larger one.~The larger resistance still carries branch current.|The reciprocal of resistance is conductance. Adding branch conductances accounts for the total current at a common voltage; invert that total to recover resistance.|The reciprocal method works for unequal as well as equal resistors.|Can the equivalent resistance of two finite parallel resistors exceed the smaller resistor?|No. The additional conducting path makes it smaller.
p01-l10:3|Three identical 12 Ω resistors are in parallel. What is their equivalent resistance?|4 Ω.|36 Ω.~Multiplication by branch count gives the series total.|12 Ω.~The extra branches increase conductance; they do not leave the equivalent unchanged.|0.25 Ω.~0.25 is the conductance in siemens, before taking its reciprocal.|Equal branches each draw the same current. Three branches draw three times one branch’s current at the same voltage, giving one third of its resistance.|For identical parallel resistors, divide resistance by branch count.|What is the equivalent resistance of four identical 20 Ω resistors in parallel?|5 Ω.
p01-l11:1|A 6 Ω and a 12 Ω branch share a 12 V supply. Which branch carries more current?|The 6 Ω branch carries twice the current of the 12 Ω branch.|The 12 Ω branch carries twice the current because its resistance is larger.~At the same voltage, current is inversely related to resistance.|Both carry equal current because their voltages are equal.~Equal voltage only gives equal current when resistance is also equal.|The 6 Ω branch takes all the current and the 12 Ω branch takes none.~A finite parallel resistance still provides a conducting path.|The branch currents are twelve divided by six and twelve divided by twelve: two amperes and one ampere. Both branch voltage and resistance enter the calculation.|Common voltage does not mean common current.|What would make two resistive branches at the same voltage carry equal current?|Equal resistance under the same operating conditions.
p01-l11:2|A junction receives 5 A. One outgoing branch carries 2 A. What must the other branch carry in steady operation?|3 A.|7 A.~The outgoing currents must add to the incoming current, not exceed it.|2.5 A.~Equal division cannot be assumed when one branch current is already known.|5 A.~Sending the full incoming current into both paths would violate current conservation.|At a steady junction, charge does not accumulate indefinitely. The second branch must carry the part of the incoming current not carried by the first.|Apply conservation before assuming equal sharing.|If the first branch rises to 3 A while incoming current stays 5 A, what remains for the other branch?|2 A.
p01-l11:3|Why should adding calculated branch currents agree with voltage divided by equivalent resistance?|Both methods describe the same total charge-transfer rate from the source.|Equivalent resistance gives the average branch current.~Equivalent resistance describes the network’s total source demand.|The agreement proves every branch has equal resistance.~Unequal parallel resistances also satisfy both methods.|The agreement removes the need to use consistent units.~A coincidental number does not make incompatible units valid.|The equivalent resistance is defined to draw the same total current as the original network at that voltage. Branch-current addition is an independent route to that total.|An equivalent model preserves terminal behaviour, not every internal detail.|Can one equivalent resistor tell you which original branch carries the most current?|No. Individual branch resistances are still needed.
p01-l12:1|A device transfers 24 J of energy each second. What is its power?|24 W.|24 C.~Coulombs measure charge, not energy-transfer rate.|24 A.~Amperes measure charge per second, not joules per second.|24 Wh.~Watt-hours measure accumulated energy, not a rate.|One watt is one joule per second. Power measures how rapidly energy is transferred; multiplying a steady power by time gives energy.|Power is a rate; energy is an accumulated amount.|How much energy does a steady 10 W device transfer in 3 s?|30 J.
p01-l12:2|A DC load has 12 V across it and carries 2 A. What power does it receive?|24 W.|6 W.~Dividing voltage by current gives resistance.|14 W.~Adding voltage and current combines unlike quantities.|0.167 W.~Current divided by voltage gives conductance.|Voltage is energy transferred per unit charge, and current is charge transferred per second. Their product is energy transferred per second: twenty-four watts.|Multiply voltage by current to find DC electrical input power.|A DC load takes 60 W at 12 V. What current does it draw?|5 A.
p01-l12:3|Two loads each transfer 100 J. One takes 5 s and the other 10 s. How do their average powers compare?|The first has twice the average power.|They have equal power because their energies are equal.~Equal energy does not imply equal transfer rate.|The second has twice the power because it operates longer.~For fixed energy, more time means less average power.|The first has half the power because its operating time is shorter.~Shorter transfer time gives a higher rate for the same energy.|Average power is energy divided by elapsed time. The powers are twenty watts and ten watts, despite the equal total energy.|Compare rates using both amount and time.|If power stays constant and operating time doubles, what happens to transferred energy?|It doubles.
p01-l13:1|Current and resistance are known for a DC resistor. Which expression gives its heating power?|Current squared multiplied by resistance.|Current multiplied by resistance.~That product gives voltage, not power.|Current squared divided by resistance.~Resistance belongs in the numerator when current is the known quantity.|Voltage squared multiplied by resistance.~Using voltage instead would require division by resistance.|Substitute voltage equals current times resistance into power equals voltage times current. This gives current squared times resistance.|Choose the power form that matches the known quantities.|Can heating power be found from current alone when resistance is unknown?|No. The resistance or another sufficient electrical quantity is also needed.
p01-l13:2|A connection carries the same current after its contact resistance doubles. What happens to its resistive heating power?|It doubles.|It halves because resistance reduces current.~The question holds current constant; it does not hold voltage across the contact constant.|It rises fourfold because resistance is squared.~Current is squared in this power relationship, not resistance.|It stays unchanged because current is unchanged.~At fixed current, resistance still directly affects heating.|Heating power is current squared times resistance. With current held fixed, doubling contact resistance doubles the local heat production.|A poor joint can overheat without an increase in circuit current.|Why can a load keep working while a joint overheats?|The joint can still conduct the load current while dissipating excessive heat locally.
p01-l13:3|Current through a fixed resistance rises from 2 A to 4 A. How does heating power change?|It becomes four times as large.|It becomes twice as large.~Heating depends on current squared, not current alone.|It becomes half as large.~Increasing current does not reduce resistive heating at fixed resistance.|It stays unchanged because resistance is unchanged.~Fixed resistance does not mean fixed power when current changes.|The current has doubled. Squaring that change gives a factor of four, so the same resistance dissipates four times the power.|Doubling current and doubling power are not equivalent.|At fixed resistance, what happens to heating power if current is halved?|It falls to one quarter.
p01-l14:1|Voltage and resistance are known for a resistor. Which operation finds its power directly?|Square the voltage, then divide by resistance.|Divide voltage by resistance without squaring.~That finds current.|Square the voltage, then multiply by resistance.~Resistance must divide the squared voltage in this form.|Divide resistance by voltage squared.~That inverts the power relationship.|Substitute current equals voltage divided by resistance into power equals voltage times current. The result is voltage squared divided by resistance.|The current formula and the power formula answer different questions.|What extra step turns voltage divided by resistance into power?|Multiply the resulting current by voltage.
p01-l14:2|Voltage across a constant resistance doubles. How does power change?|It increases fourfold.|It doubles.~Power depends on voltage squared at fixed resistance.|It halves.~A higher voltage produces greater current and power in this model.|It stays fixed because resistance is fixed.~Both voltage and resulting current affect power.|With unchanged resistance, doubling voltage doubles current. Multiplying the doubled voltage by doubled current gives four times the power.|The constant-resistance assumption is essential to this prediction.|Why might a real hot filament not follow the same fourfold prediction exactly?|Its resistance changes with temperature, so the constant-resistance assumption no longer holds.
p01-l14:3|A 12 Ω resistor has 24 V across it. What power does it dissipate?|48 W.|2 W.~Twenty-four divided by twelve gives current in amperes, not power.|288 W.~Multiplying voltage by resistance does not give power.|24 W.~Power is not numerically equal to voltage merely because both describe the same load.|Square twenty-four volts and divide by twelve ohms. The result is forty-eight watts; the corresponding current is two amperes.|Check both the numerical operation and the output unit.|Using 24 V and the calculated 2 A, how can the result be checked?|Multiply them to obtain 48 W.
p01-l15:1|A heater is rated 2 kW. What does the rating describe?|Its rate of electrical energy transfer at the stated operating condition.|Its total energy consumption each day.~Daily energy also depends on operating time and duty cycle.|Its stored energy when disconnected.~A power rating is not stored energy.|Its charge transfer per second.~Charge transfer per second is current, measured in amperes.|Kilowatts measure power, a rate. To calculate energy, combine that rate with the time for which it applies.|kW is power; kWh is energy.|Can a 2 kW rating alone tell you the heater’s daily energy use?|No. Its operating time and actual power pattern are also needed.
p01-l15:2|A heater runs steadily at 2 kW for 3 h. How much energy does it use?|6 kWh.|0.667 kWh.~Energy is power multiplied by time, not divided by time.|5 kWh.~Adding power and time combines different quantities.|6 kW.~The product is energy and must be expressed in kWh here, not kW.|Each hour at two kilowatts transfers two kilowatt-hours. Three such hours transfer six kilowatt-hours.|Keep the rate separate from the accumulated result.|The heater runs for half as long at the same power. What energy does it use?|3 kWh.
p01-l15:3|Which energy is equivalent to 1 kWh?|3.6 million joules.|1,000 joules.~A kilowatt is 1,000 joules per second, and an hour contains 3,600 seconds.|3,600 joules.~This omits the factor of 1,000 in kilowatt.|1,000 joules per second.~That is a power of one kilowatt, not an energy.|One kilowatt-hour combines one thousand joules per second with three thousand six hundred seconds. Multiplying gives 3.6 million joules.|A watt-hour contains a time interval; a watt does not.|How many kilowatt-hours does 500 W used for 2 h represent?|1 kWh.
p01-l16:1|A resistance heater warms its surroundings. Which description accounts for the energy?|Electrical energy is transferred into thermal energy in the resistive element.|Electrons are consumed and their charge becomes heat.~Charge is conserved; it is energy that is transferred.|The element creates additional energy once it becomes hot.~The heat comes from supplied energy, not energy creation.|The element stores all incoming energy as electric charge.~A functioning heater transfers energy thermally rather than accumulating all charge.|The electric field does work on charge carriers. Interactions in the resistive material transfer energy to its thermal motion and surroundings.|A heater converts energy; it does not use up current.|Why is resistive heating useful in an element but undesirable in a loose terminal?|The element is designed to dissipate heat; a loose terminal concentrates unwanted heating at a connection.
p01-l16:2|A contactor coil moves its armature when energised. Which effect causes the motion?|The magnetic field produced by coil current.|Heating expansion of the contact screws.~Thermal expansion is not the normal contactor operating mechanism.|Charge accumulating permanently on the armature.~A contactor’s coil operates magnetically, not by permanent charge accumulation.|Chemical consumption of the coil conductor.~Normal coil operation does not require chemical consumption of copper.|Current in the coil produces a magnetic field that exerts force on the armature. The mechanism then changes the contact positions.|Coil current produces magnetic force; the contacts carry the controlled load.|Why can a small control circuit switch a separate larger load through a contactor?|The coil operates the mechanism, while separately rated main contacts carry the load current.
p01-l16:3|During suitable battery charging, which useful effect of current occurs?|Electrical energy supports chemical changes that store energy.|Charge disappears as it turns into chemicals.~Charge participates in reactions but is not simply destroyed.|The battery stores all energy only as conductor heating.~Heating is a loss; intended storage involves chemical change.|Current can have no chemical effect because electrons move only in metals.~Charge transport and chemical reactions also occur in battery materials and electrolytes.|A charging source drives reactions in the battery’s electrochemical system. The stored energy can later support electrical output within the battery’s operating limits.|Chemical storage is different from resistive heating.|Does a warming battery prove that charging is effective and safe?|No. Heating alone does not establish correct charging conditions or useful stored energy.
p01-l17:1|Current through a coil reverses. What happens to its magnetic polarity?|Its magnetic polarity reverses.|Its polarity stays fixed because the winding shape is unchanged.~Winding geometry and current direction together determine polarity.|The field disappears permanently.~Reversed current still produces a field, with reversed direction.|The coil gains a second field that cancels the first regardless of current.~The previous current is replaced; there are not two independent steady currents to cancel.|The field direction depends on the direction of conventional current around the turns. Reversing that current reverses the field and coil poles.|A current reversal is also a magnetic-direction reversal.|If both winding direction and current direction are reversed, what happens to the resulting polarity?|The two reversals cancel, giving the original polarity for the same geometry reference.
p01-l17:2|At the same current and comparable geometry, a coil has twice as many turns. What is the expected effect on its magnetising action?|It increases because the ampere-turns increase.|It halves because each turn receives less current.~Series turns carry the same coil current.|It stays unchanged because only voltage determines the field.~Current and turns are central to magnetising action.|It necessarily increases by exactly four times.~Doubling turns does not create a general square-law increase in field.|The magnetic effects of the turns combine. More turns at the same current increase magnetising action, although actual flux also depends on the magnetic circuit and saturation.|More turns at fixed current is different from more turns at fixed voltage.|Why might adding turns at unchanged supply voltage fail to increase the field as expected?|The added wire can increase resistance and reduce current.
p01-l17:3|Why can a suitable ferromagnetic core strengthen a coil’s magnetic effect?|It provides a more favourable path for magnetic flux than air.|It supplies extra electric current without a source.~A core does not create coil current.|It makes winding resistance zero.~Magnetic permeability is different from electrical resistance.|It guarantees unlimited flux as current rises.~Core saturation limits the relationship between magnetising force and flux.|A suitable core has high magnetic permeability compared with air. It changes the magnetic circuit and can concentrate flux, subject to geometry and saturation.|A core guides magnetic flux; it is not an electrical power source.|Why must increasing coil voltage not be used casually to obtain more force?|The coil may overheat or exceed its rating, and magnetic saturation can limit the useful gain.
p01-l18:1|A stationary coil links a magnetic field that is constant with time. What sustained voltage is induced by that field alone?|Zero, because flux linkage is not changing.|A constant voltage proportional only to the field strength.~A field’s presence alone is insufficient; its linkage must change.|An alternating voltage because the coil has many turns.~Turns increase induction from a change; they do not create the change.|A rising voltage for as long as the field remains present.~Constant linkage does not accumulate induced voltage over time.|Induced voltage depends on the rate of change of flux linkage. If that linkage remains constant, the induction contribution is zero.|Magnetic flux and changing magnetic flux are different conditions.|Can a stationary coil have induced voltage in a changing field?|Yes. Flux linkage can change without mechanical motion.
p01-l18:2|The same flux-linkage change occurs in half the time. How does the average induced-voltage magnitude change?|It doubles.|It halves because the event is shorter.~The same change in less time has a greater rate of change.|It stays the same because the total change is the same.~Induced voltage depends on how quickly the change occurs.|It becomes four times as large.~Halving the time doubles the average rate; it does not square it.|For the same total flux-linkage change, average induced voltage is inversely related to the elapsed time. A faster change gives a greater magnitude.|Induction depends on a rate of change, not just a final field value.|What happens if the same change takes twice as long?|The average induced-voltage magnitude halves.
p01-l18:3|Two coils link the same changing flux per turn. One has twice as many turns. How do their induced voltages compare?|The coil with twice the turns has twice the induced voltage.|Both have equal induced voltage because the flux per turn is equal.~The voltage contributions of the linked turns combine.|The coil with more turns has half the voltage.~Additional linked turns increase, rather than divide, the induced voltage.|The coil with more turns has four times the voltage.~Turns enter the flux-linkage relationship directly, not squared.|Flux linkage is the number of linked turns multiplied by flux per turn. Doubling the turns doubles its rate of change when the flux change per turn is unchanged.|Compare flux per turn separately from total flux linkage.|Why do transformer winding turns matter to the voltage ratio?|Windings linking the same core-flux change develop voltages proportional to their turns.
p01-l19:1|A generator coil rotates in a magnetic field. What directly produces its induced voltage?|The changing magnetic flux linkage as it rotates.|Rotation creating electric charge inside the conductor.~A generator transfers energy; it does not need to create charge.|The resistance becoming zero once the coil moves.~Motion does not remove the conductor’s resistance.|A constant flux linkage that grows voltage over time.~A constant linkage produces no induction contribution.|Rotation changes the coil’s orientation relative to the field. The resulting change in flux linkage induces voltage, supplied energetically by the mechanical drive.|Mechanical motion matters through its effect on flux linkage.|Would rotating a coil where it links no magnetic flux produce the same generator effect?|No. The relevant flux linkage must change.
p01-l19:2|Why does a simple rotating AC generator produce alternating polarity?|The direction of the flux-linkage change reverses during rotation.|The conductor alternates between positive and negative physical resistance.~Alternating polarity does not require negative resistance.|The generated charge changes from electrons to protons each half-cycle.~The carrier type does not alternate to create AC.|The rotor must reverse its mechanical direction each half-cycle.~Continuous rotation can generate alternating voltage.|During a full revolution, the coil experiences flux-linkage changes of opposite sign. The induced voltage therefore reverses even while the mechanical rotation continues in one direction.|Alternating electrical polarity does not require reversing mechanical rotation.|What quantity counts the number of complete electrical cycles each second?|Frequency, measured in hertz.
p01-l19:3|A generator’s pole count stays fixed while its rotational speed increases. What happens to electrical frequency?|It increases in proportion to rotational speed.|It decreases because each cycle is completed more quickly.~More cycles per second means higher frequency.|It stays fixed because the pole count is fixed.~Frequency depends on speed as well as pole count.|Only voltage can change; timing is independent of rotation.~Rotation sets how often the flux pattern repeats.|With a fixed number of poles, each mechanical revolution produces a fixed number of electrical cycles. More revolutions per second therefore produce more cycles per second.|Frequency concerns repetition rate, not voltage amplitude.|At fixed pole count, what happens to frequency if rotational speed halves?|It halves.
p01-l20:1|An ideal sine wave reaches its positive peak. How does its instantaneous value then change?|It falls smoothly through zero towards the negative peak.|It jumps immediately to the negative peak.~An instantaneous jump describes a different waveform, not an ideal sine wave.|It remains at the peak until the next cycle begins.~An ideal sine varies continuously throughout the cycle.|It returns to zero and stays there for the negative half-cycle.~A full sine wave includes a negative half-cycle.|A sine wave is a continuous periodic change. Its positive and negative halves join smoothly through zero.|Waveform shape and waveform frequency are separate properties.|Can two sine waves have the same frequency but different peak values?|Yes. Their amplitudes can differ while their periods are equal.
p01-l20:2|For a sine wave starting at zero and rising, when does it first reach its positive peak?|After one quarter of a cycle, at 90°.|After half a cycle, at 180°.~At 180° this sine wave crosses zero again.|After a full cycle, at 360°.~A full cycle returns to the starting phase.|Immediately at 0°.~The stated starting value is zero, not the peak.|One full cycle spans 360 degrees. A sine wave starting at a rising zero crossing reaches its positive maximum after a quarter cycle.|Phase position identifies where you are within a cycle.|Where is the negative peak for this same reference?|At 270°, or three quarters of a cycle.
p01-l20:3|A sine wave has equal positive and negative half-cycles. What is its average value over a complete cycle?|Zero.|Its positive peak.~The negative half-cycle must also be included in the average.|Its RMS value.~RMS is a different measure that does not cancel the squared negative values.|Half its positive peak.~That ignores the full shape and the negative half-cycle.|Equal positive and negative areas cancel in the arithmetic cycle average. A nonzero RMS value can still describe its heating effect.|Zero average voltage does not mean zero RMS voltage or no energy transfer.|Why can AC heat a resistor despite a zero cycle-average current?|Heating depends on current squared, which is positive in both half-cycles.
p01-l21:1|A waveform’s peak voltage doubles while its period stays unchanged. Which property changes?|Amplitude changes; frequency stays the same.|Frequency doubles; amplitude stays the same.~Peak size is amplitude, not cycle count.|Both amplitude and frequency must double.~Amplitude and period can vary independently.|Period halves because the peak is larger.~Peak voltage does not determine the time for a cycle.|Amplitude describes the size of the waveform. Frequency is determined by its period, so an unchanged period means unchanged frequency.|Separate vertical size from horizontal timing.|If period halves while peak voltage is fixed, which quantity doubles?|Frequency.
p01-l21:2|A waveform completes 50 cycles each second. What is its frequency?|50 Hz.|50 V.~Volts describe potential difference, not cycles per second.|0.02 Hz.~0.02 is the period in seconds for this waveform.|50 s.~Seconds measure time, not a repetition rate.|Frequency counts complete cycles per second. The hertz is the unit for that rate.|Frequency is a rate; period is a time.|How many cycles does a 50 Hz waveform complete in 2 s?|100 cycles.
p01-l21:3|What is the period of a 50 Hz waveform?|20 ms.|50 ms.~Period is the reciprocal of frequency, not its numerical value in milliseconds.|2 ms.~The reciprocal is 0.02 seconds, not 0.002 seconds.|0.02 ms.~The reciprocal gives seconds before conversion to milliseconds.|One divided by fifty gives 0.02 seconds per cycle. Multiplying seconds by one thousand gives twenty milliseconds.|Calculate in base units before changing the prefix.|What happens to period if frequency increases to 100 Hz?|It halves to 10 ms.
p01-l22:1|Which statement correctly distinguishes resistance from reactance?|Resistance dissipates real power, while ideal reactance stores and returns energy through a field.|Resistance acts only on DC, while reactance acts only on AC.~Resistance affects AC and DC; reactance describes frequency-dependent AC opposition.|Reactance destroys charge while resistance stores it.~Neither component destroys charge; they describe different circuit behaviour.|Resistance and reactance are two names for the same property.~They can both oppose AC current, but they have different energy and phase behaviour.|Resistance converts electrical energy into heat. Ideal inductive or capacitive reactance stores energy temporarily in a field and returns it to the circuit. Both affect AC current, but in different ways.|Energy dissipation is different from energy exchange with a field.|Why can an ideal inductor have substantial AC opposition without dissipating real power?|Its reactance comes from energy moving into and out of its magnetic field, rather than resistive heating.
p01-l22:2|What does an ideal inductor or capacitor do with energy during an AC cycle?|It stores energy in a magnetic or electric field and returns it to the circuit.|It permanently consumes all supplied energy as heat.~That describes resistance, not ideal reactive behaviour.|It creates electrical energy without a source.~Field storage can return energy but does not create net energy.|It prevents current at every frequency.~Reactance depends on component type and frequency; it is not an automatic open circuit.|Reactive components exchange energy with the circuit. In an ideal model, the energy taken into a field during part of the cycle is returned during another part.|Temporary storage is not the same as permanent loss.|Why does a real inductor still become warm during operation?|Its winding resistance and other losses can dissipate real power in addition to its reactive field behaviour.
p01-l22:3|A series AC circuit contains resistance and inductive reactance. What does its impedance represent?|The total opposition to AC current, including the phase relationship between resistance and reactance.|The arithmetic sum of every voltage reading in the circuit.~Impedance concerns the current–voltage relationship, not a list of voltages.|Only the component that dissipates the most heat.~Reactance also contributes to AC opposition even if ideal reactance does not dissipate real power.|The stored charge in the circuit at one instant.~Charge is a different quantity from impedance.|Impedance combines resistance and reactance for the stated AC condition. In a simple series R–L circuit, they are perpendicular components, so magnitude is not found by ordinary addition.|The magnitude of impedance is not generally R plus X.|If frequency rises in a simple R–L circuit, what can happen to impedance magnitude?|It can increase because inductive reactance increases with frequency.
p01-l23:1|What does inductance oppose most directly?|A change in current through the coil.|Any steady current, even after conditions have settled.~A steady DC current can flow through an ideal inductor after its transient response.|Voltage at the coil terminals regardless of current behaviour.~Inductance responds to changing current and flux linkage, not voltage as an isolated property.|Only current in the opposite direction to the winding arrow.~The effect depends on change in current, not an arbitrary diagram direction.|A changing current changes the coil’s magnetic field. The resulting induced voltage opposes that change, which is why inductance resists rapid current variation.|Inductance opposes change in current, not current itself.|Why can a coil pass steady DC after the switching transient in an ideal model?|Once the current is constant, its magnetic flux is no longer changing, so there is no continuing induced opposition from that change.
p01-l23:2|What creates the back electromotive force in a coil whose current is changing?|The changing magnetic field produced by the changing coil current.|The insulation becoming electrically charged.~Insulation is not the source of the coil’s induced voltage in this model.|The coil’s resistance converting current directly into a reverse voltage.~Resistance causes voltage drop but does not create the inductive back emf mechanism.|The supply reversing polarity at every instant.~Back emf can occur during a current change with one-polarity DC supply as well as in AC circuits.|Changing current changes magnetic flux linkage. The coil’s induced voltage acts in a direction that opposes the current change, consistent with Lenz’s law.|Resistive voltage drop and induced back emf have different causes.|Why can a coil produce a voltage spike when its current is interrupted quickly?|The rapid collapse of magnetic flux can induce a voltage that opposes the sudden decrease in current.
p01-l23:3|How does inductive reactance change when frequency increases and inductance stays fixed?|It increases.|It decreases because each cycle is shorter.~More rapid current change increases inductive opposition.|It stays fixed because the winding resistance is fixed.~Winding resistance and inductive reactance are different properties.|It becomes zero when frequency is high enough.~Higher frequency does not make an inductor an ideal short circuit in AC.|Inductive reactance is proportional to frequency and inductance. Higher frequency means the current must change direction more rapidly, so the induced opposition is greater.|AC frequency affects inductive reactance; DC resistance alone does not describe it.|At the same frequency, what happens to inductive reactance if inductance doubles?|It doubles in the ideal relationship.
p01-l24:1|In a series resistance–inductance impedance triangle, what does the horizontal side represent?|Resistance, measured in ohms.|Inductive reactance, measured in ohms.~Inductive reactance is the perpendicular reactive side in this model.|Real power, measured in watts.~Power is a different triangle quantity, with different units.|The total impedance magnitude.~Impedance is the resultant side, not one component.|The resistance component lies on the horizontal axis. It is in phase with current in the simple series R–L model, unlike inductive reactance.|Impedance components and power components use different triangles.|Which side represents total impedance magnitude in this triangle?|The hypotenuse, or resultant side.
p01-l24:2|In a series resistance–inductance impedance triangle, what does the vertical reactive side represent?|Inductive reactance.|Resistance.~Resistance is the horizontal in-phase component.|Capacitance in farads.~Capacitance is not the unit or component shown in this R–L triangle.|Real power in watts.~The triangle describes impedance components, all expressed in ohms.|Inductive reactance is perpendicular to resistance because its voltage is 90 degrees out of phase with the resistive voltage in this model. The vertical side is therefore the reactive component.|A right-angle impedance triangle is not a circuit layout drawing.|If the inductance is replaced by a capacitor, what changes about the reactive component?|It becomes capacitive reactance with the opposite phase sign.
p01-l24:3|Why is impedance magnitude not normally found by adding resistance and inductive reactance as ordinary numbers?|Their voltage components are 90 degrees apart in phase, so they combine as perpendicular vectors.|They use different units and therefore cannot be combined.~Both are expressed in ohms; phase relationship is the reason for vector combination.|Reactance must always be smaller than resistance.~Either component can be larger in a particular circuit.|Resistance and reactance occur in separate circuits only.~They can occur together in the same AC circuit.|In a series R–L circuit, resistive and reactive voltage components are at right angles. The impedance magnitude is therefore the square root of resistance squared plus reactance squared, not their simple sum.|Same units do not guarantee ordinary arithmetic addition.|When would ordinary addition be valid for two impedance contributions?|When the contributions have the same phase angle under the stated model.
p01-l25:1|What does capacitance measure?|Charge stored per volt of applied potential difference.|Voltage produced by one coulomb of charge.~That reverses the capacitance relationship.|Energy dissipated per second by a capacitor.~Energy per second is power, not capacitance.|The resistance of a capacitor on DC after a long time.~A capacitor’s DC steady-state behaviour is not its capacitance value.|Capacitance relates stored charge to applied voltage: Q equals C times V. A larger capacitance stores more charge for the same voltage under the stated conditions.|Charge, voltage and capacitance are distinct quantities.|If voltage stays the same and capacitance doubles, what happens to stored charge?|It doubles in the ideal relationship.
p01-l25:2|Two capacitors are connected in parallel. How is their equivalent capacitance found?|Add their capacitance values.|Take the reciprocal of the sum of reciprocals.~That rule applies to capacitors in series, not parallel.|Use only the larger capacitance.~Both parallel branches store charge at the common voltage.|Multiply the capacitances together.~That does not preserve the correct units or relationship.|Parallel capacitors share the same voltage. Each stores charge, so total charge at that voltage is the sum; their capacitances therefore add directly.|Parallel capacitors add like parallel conductances, not like parallel resistances.|Two 10 microfarad capacitors are parallel. What is the equivalent capacitance?|20 microfarads.
p01-l25:3|Two identical capacitors are connected in series. How does their equivalent capacitance compare with one capacitor?|It is lower: half the capacitance of either one.|It is double because there are two storage components.~Series capacitors share charge, so the voltage divides and equivalent capacitance falls.|It is unchanged because the same charge passes through both.~Shared charge does not mean unchanged voltage–charge ratio for the pair.|It is zero because DC cannot pass continuously through a capacitor.~Steady DC current and capacitance value are different ideas.|Series capacitors carry the same charge, while their voltages add. For identical capacitors, the pair needs twice the voltage for the same charge, so its equivalent capacitance is half one capacitor’s value.|Series connection can reduce equivalent capacitance even though there are more components.|Three identical 30 microfarad capacitors are in series. What is their equivalent capacitance?|10 microfarads.
p01-l26:1|What does power factor compare in an AC circuit?|Real power with apparent power.|Apparent power with reactive power.~Power factor is real power divided by apparent power.|Line current with conductor resistance.~Those quantities affect losses but do not define power factor.|Energy used today with energy stored in a battery.~Power factor describes an operating relationship, not accumulated energy.|Power factor is the ratio of real power to apparent power for the stated AC condition. It shows how much of the supply’s voltage–current product corresponds to net energy transfer.|Power factor is dimensionless; it is not a power unit.|A load takes 8 kW at 10 kVA. What is its power factor?|0.8.
p01-l26:2|How can a reactive load have power factor below one?|Voltage and current are out of phase, so not all apparent power becomes real power.|The load has no resistance, so it consumes no current.~A reactive load can carry substantial current; phase relationship is the key issue.|The supply voltage becomes zero for part of every cycle.~A sinusoidal supply crosses zero, but that alone does not explain power factor.|The load converts all real power into charge.~Real power is net energy transfer, not charge conversion.|Reactive components exchange energy with fields, shifting current relative to voltage. That phase displacement reduces real power relative to apparent power in the simple sinusoidal model.|Phase displacement is not the same as lost supply voltage.|Can a load have low power factor while still doing useful work?|Yes. It can draw real power and also require reactive current.
p01-l26:3|A load’s real power and supply voltage remain fixed while its power factor falls. What happens to supply current?|It increases.|It decreases because less real power is being used.~The question holds real power fixed; lower power factor raises apparent demand and current.|It stays unchanged because voltage is unchanged.~At fixed voltage, current also depends on apparent power and power factor.|It becomes zero because reactive power cancels real power.~Reactive and real power do not cancel into zero supply current in this situation.|At fixed real power and voltage, lower power factor means the supply must deliver more apparent power. That requires more current, increasing conductor and equipment loading.|Useful output can be unchanged while current rises.|Why can improving power factor reduce cable heating without eliminating the useful load?|It reduces the current needed for the same real power, reducing resistive losses.
p01-l27:1|What does real power in watts represent?|Net electrical energy converted or transferred each second.|Energy moving back and forth in fields with no net conversion.~That describes reactive power in vars.|The voltage–current product regardless of phase relationship.~That is apparent power in VA.|Charge transferred through one point each second.~That is current in amperes.|Real power is the part of AC power associated with net energy transfer to heat, motion or other useful effects. It is measured in watts.|Real power and apparent power have different meanings even when their numbers match at unity power factor.|Does a motor with real input power necessarily convert all of it to shaft output?|No. Losses mean some real input power becomes heat and other losses.
p01-l27:2|What does reactive power in vars represent in an ideal AC reactive element?|The rate at which energy is exchanged with electric or magnetic fields.|Net useful energy conversion each second.~That describes real power.|The maximum voltage the supply can provide.~Voltage is a separate electrical quantity.|A permanent store of charge in the conductor.~Reactive power describes cyclic energy exchange, not stored charge at one instant.|An ideal inductor or capacitor stores energy in a field during part of the cycle and returns it later. Reactive power quantifies that exchange in vars.|Field-energy exchange is distinct from resistive energy dissipation.|Why can a circuit have reactive power without an ideal resistor heating from it?|The ideal reactive element returns stored field energy instead of dissipating it as heat.
p01-l27:3|What does apparent power in volt-amperes represent for a sinusoidal AC load?|The RMS voltage–current product supplied to the load.|Only the real power that becomes useful output.~Real power is one component of apparent power.|Only the reactive power exchanged with fields.~Reactive power is another component, not the whole apparent demand.|The energy used over one hour.~Energy needs a time interval and is not measured in VA.|Apparent power expresses the RMS voltage and current the supply and equipment must support. Its relationship with real and reactive power is represented by the power triangle.|VA describes supply loading; kWh describes accumulated energy.|Why can a cable need to carry more current for 10 kW at low power factor than at unity power factor?|The apparent power, and therefore current at a given voltage, is higher.
p01-l28:1|Why is a voltmeter connected in parallel with the points being investigated?|It measures the potential difference between those two points.|It must carry the full load current to measure voltage.~Carrying full load current is the series ammeter role.|It measures the resistance between the points using its own source.~Resistance measurement uses a different function on an isolated circuit.|It forces both points to the same voltage.~A voltmeter observes the difference; its high input resistance limits circuit disturbance.|Voltage is defined between two points. A voltmeter therefore connects across those points and ideally draws negligible current compared with the circuit being measured.|Voltage is across; current is through.|Where should an ammeter normally be connected to measure a load current?|In series so the load current passes through it.
p01-l28:2|Why does a voltmeter normally have high input impedance?|To draw very little current and reduce its effect on the circuit.|To increase the current through the circuit so the reading is clearer.~A measurement should avoid materially altering the quantity it seeks to observe.|To create a short circuit across the measured points.~High impedance is the opposite of a low-resistance shunt path.|To store the circuit’s energy before displaying a result.~The meter’s input impedance is about loading, not energy storage.|A finite-resistance meter becomes another parallel branch. High input impedance makes its branch current small, limiting loading error in most voltage measurements.|Measuring equipment can change the circuit if its input is not suitable.|Why can a high-impedance meter sometimes show a voltage on an open conductor?|Very small coupled currents can produce a reading even when the source cannot deliver useful load current.
p01-l28:3|Before measuring voltage in an installation, which combination must suit the task?|Meter function, AC or DC mode, range, lead sockets and measurement category.|Only the voltage range printed on the meter.~Range alone does not establish correct function, lead input or transient category.|Only a continuity beep from the test leads.~Lead continuity does not establish an appropriate voltage-measurement setup.|Any socket arrangement if the probes touch insulated conductors.~Incorrect sockets can defeat instrument protection or create a dangerous measurement connection.|The instrument and leads must be configured for the quantity, source type and foreseeable conditions. A suitable category and correct input sockets are part of using a meter safely.|A displayed number is only meaningful when the measurement setup is suitable.|Why should a meter be proved on a known source before relying on a dead-test indication?|It confirms that the instrument and leads are functioning before the critical check.
p01-l29:1|Why is a conventional ammeter connected in series with the load?|The load current must pass through the meter’s current path.|A series connection gives the meter the full supply voltage without current.~Voltage across a component and current through it are different measurements.|It prevents any current from reaching the load.~An ammeter is intended to allow the measured current path, within its rating.|It makes resistance measurement unnecessary.~Current measurement does not replace other tests or circuit calculations.|An ammeter measures current through its internal shunt or sensor, so it belongs in the path whose current is required. Its current input is designed to have low resistance.|An ammeter measures through a path; a voltmeter measures across points.|What can happen if an ammeter current input is placed directly across a voltage source?|Its low-resistance path can create a high-current fault.
p01-l29:2|Why do multimeters use dedicated current input sockets and internal protection?|Current measurement may place a low-resistance path in series with the circuit, so the socket and fuse must suit the expected current.|The sockets provide different colours for identifying voltage polarity.~Socket function concerns internal circuit routing and protection, not colour.|The current socket makes voltage measurement more accurate across a source.~Using a current socket across a source can be dangerous rather than more accurate.|Every socket has identical protective capacity.~Current ranges and inputs can have different fuses, ratings and limits.|Meter current paths may be fused and rated differently from voltage inputs. Select the stated socket and range before making the connection, and check the meter instructions.|Input selection is part of the measurement method, not an afterthought.|Why should the leads be moved out of a current socket after the measurement?|It reduces the chance of later connecting a low-resistance current path across a voltage source by mistake.
p01-l29:3|A load current is unknown. What is the safer starting approach, subject to the instrument instructions?|Use a suitable higher current range and connection method, then reduce range if appropriate.|Start on the lowest range because it has the best resolution.~An unknown current can exceed the lowest range or its protection.|Connect the current input across the supply to see the maximum current.~That can create a short circuit instead of measuring load current.|Assume the load rating always equals the actual current.~Starting conditions, faults and inrush can differ from a nameplate value.|Choose a range and connection that can safely accommodate the credible current and inrush. Higher range may trade resolution for protection until the reading is known.|Resolution is useful only after the connection is safe and within rating.|Why might a motor’s first current be higher than its normal running current?|Starting or inrush conditions can demand more current before the motor reaches normal operation.
p01-l30:1|What condition is required before measuring circuit resistance with a meter?|The circuit must be safely isolated and proven de-energized.|The circuit must be energised so the meter can detect its normal resistance.~A resistance meter supplies its own test signal; external voltage can damage it or distort the result.|Only the load switch must be turned off.~An open control switch does not establish isolation from every source.|The meter probes must be placed across a live supply first.~Live voltage testing and resistance testing use different safe procedures.|A resistance meter applies its own small test source. Isolate all relevant supplies, secure against reconnection as required and prove the circuit dead before connecting it.|A stopped load or open switch is not proof of isolation.|Why can an open wall switch be insufficient before resistance testing?|A line conductor or another supply path may still remain energised.
p01-l30:2|A resistor remains connected in parallel with another path. How can that affect an ohmmeter reading?|It can make the reading lower than the resistor’s own resistance.|It can only make the reading higher because there are more components.~Parallel paths provide extra conduction and reduce equivalent resistance.|It cannot affect the reading if the resistor looks intact.~Electrical paths, not appearance, determine the meter result.|The meter subtracts the second path automatically.~An ohmmeter measures the combined network unless components are suitably separated.|The meter drives test current through every available connected path. Parallel paths share that current, so the displayed equivalent resistance can be lower than the individual resistor’s value.|A component reading can represent a network rather than one component.|How can a resistor be prepared for a meaningful individual measurement?|Isolate the circuit and separate it sufficiently from parallel paths, following the applicable procedure.
p01-l30:3|Why can probe and lead resistance matter when measuring a very small resistance?|It adds to the displayed value and can be a large fraction of the result.|It is automatically removed by every meter without setup.~Some instruments or methods require a null or compensation procedure.|It reduces the displayed resistance because leads act in parallel.~The leads are normally in series with the measured path.|It matters only when the circuit is energised.~Lead resistance is a measurement issue even on an isolated circuit.|When the expected resistance is small, a fraction of an ohm from leads and contacts can be significant. Use the instrument’s appropriate zero or compensation method and clean, sound connections.|Instrument error must be compared with the scale of the quantity measured.|Why should the leads be rechecked after changing a test lead or clip?|The added resistance can change, so the earlier compensation may no longer be valid.
p01-l31:1|What physical effect lets a clamp meter sense current without opening the conductor?|The magnetic field produced by current in the conductor.|The conductor’s insulation colour.~Colour does not create a measurable current field.|The voltage stored between the conductor and earth.~A clamp senses magnetic effect of current, not voltage alone.|The conductor’s temperature at no load.~Heating can accompany current but is not the clamp’s sensing mechanism.|Current produces a magnetic field around a conductor. A clamp senses that field with its jaws closed around the conductor and converts it to a current indication within its specifications.|Clamp meters sense field from current; voltmeters sense potential difference.|Why can a clamp meter show a nonzero reading on one conductor without making electrical contact?|The conductor’s magnetic field links the clamp sensor.
p01-l31:2|Why should a clamp normally surround one conductor of the circuit?|It isolates the magnetic effect of that conductor’s current.|It adds the outgoing and returning currents to give double the load current.~Their magnetic effects oppose and largely cancel when both are enclosed.|It proves the circuit has no protective conductor.~Clamp placement does not prove conductor identity or protective continuity.|It measures voltage drop along the cable.~A clamp measures current-related magnetic field, not voltage drop.|The outgoing and returning conductors of a healthy single-phase circuit carry equal and opposite current directions. Enclosing both gives little net magnetic field, so use one conductor for ordinary load current measurement.|One-conductor load-current measurement differs from residual-current measurement.|When is it useful to clamp both line and neutral together?|When checking their residual imbalance with a suitable sensitive clamp and method.
p01-l31:3|Which condition can make a clamp-meter current reading unreliable?|An incompletely closed jaw or an unsuitable range or waveform capability.|A clean conductor with intact insulation.~Those conditions do not by themselves create a clamp reading error.|A correctly selected range with the jaws fully closed.~That is part of a sound measurement setup.|A current path passing through the centre of the jaw opening.~Position can influence accuracy, but a conductor in the specified jaw position is not inherently unreliable.|The magnetic circuit of the clamp needs fully closed jaws. Range, conductor position, waveform type and the instrument’s specified capability all affect how accurately it can interpret the field.|Measurement quality depends on the instrument setup as well as the circuit.|Why might a non-true-RMS clamp misread a distorted current waveform?|Its calculation method may assume a waveform shape that the distorted current does not follow.
`;

export const foundationRevisions: Record<string, Revision> = Object.fromEntries(rows.trim().split('\n').map(row => {
  const [key, prompt, correct, ...fields] = row.split('|');
  const [lesson, concept] = key.split(':');
  const wrong = fields.slice(0, 3).map(field => field.split('~')[0]) as Revision['wrong'];
  const errors = fields.slice(0, 3).map(field => field.split('~')[1]) as Revision['errors'];
  return [`${lesson}-q-concept-${concept}`, { prompt, correct, wrong, errors, why: fields[3], distinction: fields[4], followUp: { prompt: fields[5], answer: fields[6], why: fields[4] } }];
}));
